import sys, bisect
lines = sys.stdin.read().splitlines()
out = []
store = {}
if lines:
    m = int(lines[0])
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        if cmd[0] == 'SET':
            k, v, t = cmd[1], cmd[2], int(cmd[3])
            if k not in store: store[k] = ([], [])
            store[k][0].append(t)
            store[k][1].append(v)
        elif cmd[0] == 'GET':
            k, t = cmd[1], int(cmd[2])
            if k not in store: out.append('')
            else:
                times, vals = store[k]
                idx = bisect.bisect_right(times, t) - 1
                out.append(vals[idx] if idx >= 0 else '')
print(' '.join(out))
